package com.nyayaconnect.health; import com.nyayaconnect.common.Api; import org.springframework.jdbc.core.JdbcTemplate; import com.nyayaconnect.auth.SpringAccess; import jakarta.servlet.http.*; import java.io.IOException; import java.util.Map;
public class ReadinessServlet extends HttpServlet{private JdbcTemplate db;public void init(){db=SpringAccess.bean(getServletContext(),JdbcTemplate.class);}protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{try{db.queryForObject("select 1",Integer.class);Api.json(s,200,Map.of("status","READY","database","UP"));}catch(Exception e){Api.error(s,503,"DB_UNAVAILABLE","Database is unavailable.");}}}
